  const [data, setData] = useState<CategoryData[]>([]);



  const { data: events = [] } = useQuery<Event[]>({

    queryKey: ['/api/events'],

  });



  const { data: categories = [] } = useQuery<ServiceCategory[]>({

    queryKey: ['/api/service-categories'],

  });



  useEffect(() => {

    if (events.length && categories.length) {

      // Count events by category

      const eventsByCategoryId = events.reduce((acc, event) => {

        if (event.categoryId) {

          acc[event.categoryId] = (acc[event.categoryId] || 0) + 1;

        }

        return acc;

      }, {} as Record<number, number>);



      // Create data for chart

      const chartData = categories

        .map((category: ServiceCategory, index: number) => ({

          id: category.id,

          name: category.name,

          count: eventsByCategoryId[category.id] || 0,

          color: COLORS[index % COLORS.length],

        }))

        .filter((item: CategoryData) => item.count > 0);



      setData(chartData);

    }

  }, [events, categories]);



  if (!data.length) {

    return (

      <Card>

        <CardHeader>

          <CardTitle className="text-lg">Eventi per Categoria</CardTitle>

        </CardHeader>

        <CardContent className="flex justify-center items-center h-40">

          <p className="text-sm text-gray-500">Nessun evento disponibile</p>

        </CardContent>

      </Card>

    );

  }



  return (

    <Card>

      <CardHeader>

        <CardTitle className="text-lg">Eventi per Categoria</CardTitle>

      </CardHeader>

