                      </DropdownMenuItem>



                      <DropdownMenuItem

                        onClick={() => window.open(`/api/gallery/photos/${photo.id}/download?quality=original`, '_blank')}

                        className="pl-8"

                      >

                        Qualità originale

                      </DropdownMenuItem>



                      <DropdownMenuItem

                        onClick={() => window.open(`/api/gallery/photos/${photo.id}/download?quality=large`, '_blank')}

                        className="pl-8"

                      >

                        Qualità alta

                      </DropdownMenuItem>



                      <DropdownMenuItem

                        onClick={() => window.open(`/api/gallery/photos/${photo.id}/download?quality=medium`, '_blank')}

                        className="pl-8"

                      >

                        Qualità media

                      </DropdownMenuItem>

                    </DropdownMenuContent>

                  </DropdownMenu>

                </TooltipTrigger>

