importEventsFromGoogleCalendar.body:
  try {

    // Ottieni l'autenticazione per l'utente

    await getAuthClientForUser(userId);



    // Ottieni gli eventi da Google Calendar (limitato agli eventi futuri)

    const response = await calendar.events.list({

      calendarId: 'primary',

      timeMin: new Date().toISOString(),

      maxResults: 100,

      singleEvents: true,

      orderBy: 'startTime',

    });



    let importedCount = 0;



    if (response.data.items && response.data.items.length > 0) {

      for (const googleEvent of response.data.items) {

        if (!googleEvent.id) continue;



        // Controlla se l'evento è già presente nel database

        const [existingEvent] = await db.select()

          .from(events)

          .where(eq(events.googleCalendarEventId, googleEvent.id));



        if (existingEvent) continue; // Evento già importato, salta



        // Prepara i dati dell'evento

        const startDate = googleEvent.start?.dateTime ? 

          new Date(googleEvent.start.dateTime) : 

          (googleEvent.start?.date ? new Date(googleEvent.start.date) : new Date());



        const endDate = googleEvent.end?.dateTime ? 

          new Date(googleEvent.end.dateTime) : 

          (googleEvent.end?.date ? new Date(googleEvent.end.date) : undefined);



        // Calcola la durata in minuti

        const duration = endDate ? 

          Math.round((endDate.getTime() - startDate.getTime()) / 60000) : 

          60; // Durata predefinita: 1 ora



        // Inserisci il nuovo evento nel database

        await db.insert(events)

          .values({

            title: googleEvent.summary || 'Evento Google Calendar',

            description: googleEvent.description || '',

            location: googleEvent.location || '',

            date: startDate,

            endDate: endDate,

            duration: duration,

            eventType: 'other', // Tipo generico per eventi importati

            clientId: 1, // Utente default o placeholder (deve esistere nel database)

            status: 'upcoming',

            googleCalendarEventId: googleEvent.id,

            googleCalendarSynced: true,

          });



        importedCount++;

      }

    }



    return importedCount;

  } catch (error) {

    console.error('Errore durante l\'importazione degli eventi da Google Calendar:', error);

    throw error;

  }

}

serveStaticFixed.body:
  // Corretto il percorso per puntare alla directory dist/public nella root del progetto

  const distPath = path.resolve(process.cwd(), "dist", "public");



  if (!fs.existsSync(distPath)) {

    // Log più dettagliato per il debugging

    console.error(`Directory di build non trovata: ${distPath}`);

    console.error(`Directory corrente: ${process.cwd()}`);



    try {

      console.error(`Contenuto directory corrente:`, fs.readdirSync(process.cwd()));

    } catch (e) {

      console.error(`Impossibile leggere la directory corrente:`, e);

    }



    throw new Error(

      `Could not find the build directory: ${distPath}, make sure to build the client first`,

    );

  }



  console.log(`Serving static files from: ${distPath}`);

  app.use(express.static(distPath));



  // fall through to index.html if the file doesn't exist

  app.use("*", (_req, res) => {

    res.sendFile(path.resolve(distPath, "index.html"));

  });

}

processTemplate.body:
  if (!template) return '';



  // Ottieni le impostazioni dello studio

  const settings = await storage.getSettings();



  // Aggiungi le variabili dello studio

  const studioData = {

    studio_nome: settings?.companyName || 'Studio Arte',

    studio_email: settings?.companyEmail || 'info@studioarte.it',

    studio_telefono: settings?.companyPhone || '',

    studio_indirizzo: settings?.companyAddress || '',

    ...data

  };



  // Sostituisci le variabili nel template

  let processedTemplate = template;

  for (const [key, value] of Object.entries(studioData)) {

    if (value !== undefined && value !== null) {

      // Gestisci le date in modo speciale

      let formattedValue: string;

      // Verifica se è una data controllando se ha il metodo getMonth

      if (value && typeof value === 'object' && 'getMonth' in value) {

        formattedValue = format(value as Date, 'dd/MM/yyyy', { locale: it });

      } else {

        formattedValue = String(value);

      }



      // Sostituisci tutti gli occorrimenti

      const regex = new RegExp(`{${key}}`, 'g');

      processedTemplate = processedTemplate.replace(regex, formattedValue);

    }

  }



  return processedTemplate;

}

sendEmail.body:
  try {

    // Se non è configurata la chiave API, simula l'invio

    if (!process.env.SENDGRID_API_KEY) {

      console.log('Simulazione invio email:', {

        template: templateName,

        to: params.to,

        subject: params.subject,

        content: params.html || params.text

      });

      return true;

    }



    // Imposta la priorità predefinita se non specificata

    const priority = params.priority || EmailPriority.MEDIUM;



    // Verifica i limiti di invio email

    const isAdmin = !params.userId; // Se non è specificato userId, assume sia un'email di sistema



    if (!isAdmin) {

      // Se non è un'email di sistema, verifica i limiti del piano utente

      const canSend = await subscriptionLimitsService.canUserSendEmail(params.userId, priority);

      if (!canSend) {

        console.warn(`Limite di invio email raggiunto per l'utente ${params.userId}. Email a ${params.to} non inviata.`);



        // Registra il tentativo fallito nel log

        await db.execute(

          sql`INSERT INTO email_logs (recipient, subject, priority, sent_at, user_id, status)

              VALUES (${params.to}, ${params.subject}, ${priority}, ${new Date().toISOString()}, ${params.userId}, 'failed_limit')`

        );



        return false;

      }

    } else {

      // Se è un'email di sistema, verifica i limiti globali

      const canSend = await emailLimitService.canSendEmail(priority);

      if (!canSend && priority !== EmailPriority.CRITICAL) {

        console.warn(`Limite globale di invio email raggiunto. Email a ${params.to} non inviata.`);

        return false;

      }

    }



    // Ottieni le impostazioni per l'email del mittente

    const [appSettings] = await db.select().from(settings);

    const fromEmail = appSettings?.companyEmail || 'info@imagestudio.com';

    const fromName = appSettings?.companyName || 'Image Studio';



    // Crea il contenuto dell'email nel formato richiesto da SendGrid

    const content: {type: string, value: string}[] = [];

    if (params.text) {

      content.push({

        type: 'text/plain',

        value: params.text

      });

    }

    if (params.html) {

      content.push({

        type: 'text/html',

        value: params.html

      });

    }



    // Assicuriamoci che ci sia almeno un contenuto

    if (content.length === 0 && (params.text || params.html)) {

      content.push({

        type: 'text/plain',

        value: params.text || params.html || 'Nessun contenuto fornito'

      });

    }



    const msg = {

      to: params.to,

      from: {

        email: fromEmail,

        name: fromName

      },

      subject: params.subject,

      content: content,

      attachments: params.attachments

    };



    await sgMail.send(msg as any);



    // Registra l'email inviata nel log

    if (params.userId) {

      await db.execute(

        sql`INSERT INTO email_logs (recipient, subject, priority, sent_at, user_id, status)

            VALUES (${params.to}, ${params.subject}, ${priority}, ${new Date().toISOString()}, ${params.userId}, 'sent')`

      );

    } else {

      // Email di sistema (senza userId)

      await db.execute(

        sql`INSERT INTO email_logs (recipient, subject, priority, sent_at, status)

            VALUES (${params.to}, ${params.subject}, ${priority}, ${new Date().toISOString()}, 'sent')`

      );

    }



    return true;

  } catch (error) {

    console.error('Errore nell\'invio dell\'email:', error);



    // Registra il fallimento nel log

    if (params.userId) {

      try {

        await db.execute(

          sql`INSERT INTO email_logs (recipient, subject, priority, sent_at, user_id, status)

              VALUES (${params.to}, ${params.subject}, ${priority}, ${new Date().toISOString()}, ${params.userId}, 'failed')`

        );

      } catch (logError) {

        console.error('Errore nella registrazione del fallimento dell\'invio:', logError);

      }

    }



    return false;

  }

}

