        // Genera un nome file unico per l'immagine di copertina

        const uniqueFilename = `cover-${Date.now()}-${uuidv4().substring(0, 8)}${path.extname(req.file.originalname)}`;

        const filePath = path.join(UPLOAD_DIR, uniqueFilename);



