      // Se richiesto, inserisci anche il pagamento del saldo

      if (registraSaldo && pagamentoData) {

        await tx.insert(pagamentiCollaboratori)

          .values(pagamentoData);

      }



      return res.status(200).json(montaggioAggiornato);

    });

  } catch (error) {

