try {

  // Otteniamo il token CSRF prima di iniziare il caricamento

  const csrfToken = await getCsrfToken();

  const token = localStorage.getItem("auth_token");



  console.log("Token CSRF:", csrfToken ? "Ottenuto" : "Non disponibile");

  console.log("Token JWT:", token ? "Disponibile" : "Non disponibile");



  const xhr = new XMLHttpRequest();



  const progressPromise = new Promise<void>((resolve, reject) => {

    xhr.upload.addEventListener("progress", (event) => {

      if (event.lengthComputable) {

        const progress = Math.round((event.loaded * 100) / event.total);

        setFiles((prev) =>

          prev.map((f) =>

            f.id === file.id ? { ...f, progress } : f

          )

        );

      }

    });



    xhr.addEventListener("load", () => {

      if (xhr.status >= 200 && xhr.status < 300) {

        console.log("Risposta server upload:", xhr.responseText);

        resolve();

      } else {

        let errorMsg = "Caricamento fallito. Controlla il file e riprova.";

        let errorTitle = "Errore";



        try {

          const errorResponse = JSON.parse(xhr.responseText);

          if (errorResponse.error) {

            errorTitle = errorResponse.error;



            // Usa il messaggio dettagliato se disponibile

            if (errorResponse.message) {

              errorMsg = errorResponse.message;

            } else if (errorResponse.details) {

              errorMsg = errorResponse.details;

            }



            console.error("Errore server:", errorResponse);

          }

        } catch (e) {

          console.error("Risposta server non è JSON valido:", xhr.responseText);

        }



        // Per alcuni errori specifici, possiamo personalizzare ulteriormente il messaggio

        if (xhr.status === 409 && errorTitle === "File duplicato") {

          // Per file duplicati, non è necessario interrompere l'intero processo di caricamento

          // Aggiorniamo solo lo stato di questo file specifico

          setFiles((prev) =>

            prev.map((f) =>

              f.id === file.id

                ? { ...f, status: "error", error: errorMsg }

                : f

            )

          );



          toast({

            title: errorTitle,

            description: errorMsg,

            variant: "default"

          });



          // Risolviamo la promessa in modo che gli altri file possano continuare a essere caricati

          resolve();

          return;

        }



        // Per altri errori, continuiamo con il comportamento esistente

        reject(new Error(`HTTP Error: ${xhr.status} - ${errorMsg}`));

        toast({

          title: errorTitle,

          description: errorMsg,

          variant: "destructive"

        });

      }

    });



    xhr.addEventListener("error", () => reject(new Error("Network Error")));

    xhr.addEventListener("abort", () => reject(new Error("Upload Aborted")));

  });



  xhr.open("POST", `/api/gallery/photos`);



  // Aggiungiamo gli header necessari

  if (csrfToken) {

    xhr.setRequestHeader('X-CSRF-Token', csrfToken);

  }



  if (token) {

    xhr.setRequestHeader('Authorization', `Bearer ${token}`);

  }



  xhr.withCredentials = true; // Necessario per inviare i cookie di sessione



  xhr.send(formData);



  await progressPromise;



  setFiles((prev) =>

    prev.map((f) =>

      f.id === file.id ? { ...f, status: "success", progress: 100 } : f

    )

  );



  return { ...file, status: "success", progress: 100 };

} catch (error) {

  console.error(`Errore durante il caricamento di ${file.name}:`, error);



  let errorMessage = error instanceof Error ? error.message : "Errore sconosciuto";



  // I messaggi di errore verranno già gestiti dalla Promise



  setFiles((prev) =>

    prev.map((f) =>

      f.id === file.id

        ? { ...f, status: "error", error: errorMessage }

        : f

    )

  );



  toast({

    title: "Errore",

    description: errorMessage || `Impossibile caricare ${file.name}. Verifica il formato e la dimensione del file.`,

    variant: "destructive"

  });

  return { ...file, status: "error", error: errorMessage };

}

