export function isAdmin(req: Request, res: Response, next: NextFunction) {

  // Controlla se è autenticato

  isAuthenticated(req, res, () => {

    if ((req.user as SelectUser).role === "admin") {

      next();

    } else {

      res.status(403).json({ message: "Non autorizzato" });

    }

  });

}

